      "canonical_name": "数列极限",
      "aliases": ["ε-N定义", "数列收敛"],
      "description": "数列当n→∞时趋近于某常数的精确数学定义。"
    },
    {
      "canonical_name": "函数极限",
      "aliases": ["ε-δ定义", "函数收敛", "左极限", "右极限"],
      "description": "函数当自变量趋近某点时函数值趋近于某常数的定义。"
    },
    {
      "canonical_name": "无穷小量",
      "aliases": ["高阶无穷小", "同阶无穷小", "等价无穷小", "无穷小比较"],
      "description": "极限为零的变量，其比较与等价替换是求极限的重要工具。"
    },
    {
      "canonical_name": "函数的连续性",
      "aliases": ["连续函数", "间断点", "连续的定义"],
      "description": "函数在某点极限值等于函数值，是函数光滑性的基础。"
    },
    {
      "canonical_name": "导数",
      "aliases": ["导数的定义", "导数的几何意义", "求导", "可导"],
      "description": "函数在某点变化率的极限，几何意义为切线斜率，是微分的核心概念。"
    },
    {
      "canonical_name": "微分中值定理",
      "aliases": ["罗尔定理", "拉格朗日中值定理", "柯西中值定理"],
      "description": "包括罗尔、拉格朗日、柯西中值定理，建立导数与函数值关系的桥梁。"
    },
    {
      "canonical_name": "洛必达法则",
      "aliases": ["L'Hôpital's rule"],
      "description": "利用导数求0/0或∞/∞型极限的方法。"
    },
    {
      "canonical_name": "泰勒公式",
      "aliases": ["Taylor公式", "泰勒展开", "麦克劳林展开", "佩亚诺余项", "拉格朗日余项"],
      "description": "将函数展开为多项式，用多项式逼近函数并估计误差。"
    },
    {
      "canonical_name": "不定积分",
      "aliases": ["原函数", "反导数", "基本积分表"],
      "description": "导数的逆运算，求原函数的过程，包含基本积分公式与积分方法。"
    },
    {
      "canonical_name": "定积分",
      "aliases": ["黎曼积分", "定积分的定义", "牛顿-莱布尼茨公式", "微积分基本定理"],
      "description": "分割、近似、求和、取极限的积分定义，用于计算面积等。"
    }
  ],
